export const amenities = pgTable.withRLS(
  'amenities',
  {
    id: uuid().defaultRandom().primaryKey(),
    name: text().notNull(),
    defaultFee: numeric('default_fee', { mode: 'number', precision: 12, scale: 2 }).default(0).notNull(),
    isActive: boolean('is_active').default(true).notNull(),
    createdAt: timestamp('created_at', { withTimezone: true })
      .default(sql`now()`)
      .notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .default(sql`now()`)
      .notNull(),
  },
  (table) => [
    uniqueIndex('amenities_name_unique').using('btree', sql`lower(name)`),

    pgPolicy('amenities: members can read', { for: 'select', to: ['authenticated'], using: sql`true` }),

    pgPolicy('amenities: president can delete', {
      for: 'delete',
      to: ['authenticated'],
      using: sql`( SELECT private.has_role('president'::app_role) AS has_role)`,
    }),

    pgPolicy('amenities: president can insert', {
      for: 'insert',
      to: ['authenticated'],
      withCheck: sql`( SELECT private.has_role('president'::app_role) AS has_role)`,
    }),

    pgPolicy('amenities: president can update', {
      for: 'update',
      to: ['authenticated'],
      using: sql`( SELECT private.has_role('president'::app_role) AS has_role)`,
      withCheck: sql`( SELECT private.has_role('president'::app_role) AS has_role)`,
    }),
    check('amenities_default_fee_not_negative', sql`(default_fee >= (0)::numeric)`),
    check('amenities_name_not_blank', sql`(btrim(name) <> ''::text)`),
  ],
)

