export const transactions = pgTable.withRLS(
  'transactions',
  {
    id: uuid().defaultRandom().primaryKey(),
    kind: transactionKind().notNull(),
    categoryId: uuid('category_id').notNull(),
    periodId: uuid('period_id').notNull(),
    propertyId: uuid('property_id'),
    amount: numeric({ mode: 'number', precision: 12, scale: 2 }).notNull(),
    currency: currencyCode()
      .default(sql`private.current_currency()`)
      .notNull(),
    occurredOn: date('occurred_on')
      .default(sql`CURRENT_DATE`)
      .notNull(),
    feeMonth: date('fee_month'),
    paymentMethod: paymentMethod('payment_method').default('cash').notNull(),
    folio: text(),
    reference: text(),
    description: text().notNull(),
    notes: text(),
    createdBy: uuid('created_by')
      .default(sql`auth.uid()`)
      .notNull(),
    createdAt: timestamp('created_at', { withTimezone: true })
      .default(sql`now()`)
      .notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .default(sql`now()`)
      .notNull(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    deletedBy: uuid('deleted_by'),
    amenityReservationId: uuid('amenity_reservation_id'),
  },
  (table) => [
    foreignKey({
      columns: [table.amenityReservationId],
      foreignColumns: [amenityReservations.id],
      name: 'transactions_amenity_reservation_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.categoryId, table.kind],
      foreignColumns: [transactionCategories.id, transactionCategories.kind],
      name: 'transactions_category_fkey',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.createdBy],
      foreignColumns: [profiles.id],
      name: 'transactions_created_by_fkey',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.deletedBy],
      foreignColumns: [profiles.id],
      name: 'transactions_deleted_by_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.periodId],
      foreignColumns: [periods.id],
      name: 'transactions_period_id_fkey',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.propertyId],
      foreignColumns: [properties.id],
      name: 'transactions_property_id_fkey',
    }).onDelete('restrict'),
    index('transactions_amenity_reservation_id_idx')
      .using('btree', table.amenityReservationId.asc().nullsLast())
      .where(sql`(amenity_reservation_id IS NOT NULL)`),
    index('transactions_category_id_idx').using('btree', table.categoryId.asc().nullsLast()),
    index('transactions_fee_month_property_idx')
      .using('btree', table.feeMonth.asc().nullsLast(), table.propertyId.asc().nullsLast())
      .where(sql`((fee_month IS NOT NULL) AND (deleted_at IS NULL))`),
    index('transactions_folio_idx')
      .using('btree', table.folio.asc().nullsLast())
      .where(sql`(folio IS NOT NULL)`),
    index('transactions_folio_one_receipt')
      .using('gist', table.folio.asc().nullsLast(), table.createdAt.asc().nullsLast())
      .where(sql`((folio IS NOT NULL) AND (deleted_at IS NULL))`),
    index('transactions_live_occurred_on_idx')
      .using('btree', table.occurredOn.desc().nullsFirst(), table.createdAt.desc().nullsFirst())
      .where(sql`(deleted_at IS NULL)`),
    uniqueIndex('transactions_one_per_amenity_reservation_category')
      .using('btree', table.amenityReservationId.asc().nullsLast(), table.categoryId.asc().nullsLast())
      .where(sql`((amenity_reservation_id IS NOT NULL) AND (deleted_at IS NULL))`),
    uniqueIndex('transactions_one_per_house_month_category')
      .using(
        'btree',
        table.propertyId.asc().nullsLast(),
        table.feeMonth.asc().nullsLast(),
        table.categoryId.asc().nullsLast(),
      )
      .where(sql`((fee_month IS NOT NULL) AND (deleted_at IS NULL))`),
    index('transactions_period_id_idx').using('btree', table.periodId.asc().nullsLast()),
    index('transactions_property_id_idx')
      .using('btree', table.propertyId.asc().nullsLast())
      .where(sql`(property_id IS NOT NULL)`),

    pgPolicy('transactions: members can read', { for: 'select', to: ['authenticated'], using: sql`true` }),

    pgPolicy('transactions: treasurer can insert', {
      for: 'insert',
      to: ['authenticated'],
      withCheck: sql`( SELECT private.has_role('treasurer'::app_role) AS has_role)`,
    }),

    pgPolicy('transactions: treasurer can update', {
      for: 'update',
      to: ['authenticated'],
      using: sql`( SELECT private.has_role('treasurer'::app_role) AS has_role)`,
      withCheck: sql`( SELECT private.has_role('treasurer'::app_role) AS has_role)`,
    }),
    check('transactions_amount_positive', sql`(amount > (0)::numeric)`),
    check('transactions_description_not_blank', sql`(btrim(description) <> ''::text)`),
    check(
      'transactions_fee_month_first_day',
      sql`((fee_month IS NULL) OR (EXTRACT(day FROM fee_month) = (1)::numeric))`,
    ),
    check(
      'transactions_fee_month_needs_property',
      sql`((fee_month IS NULL) OR ((kind = 'income'::transaction_kind) AND (property_id IS NOT NULL)))`,
    ),
    check('transactions_folio_not_blank', sql`((folio IS NULL) OR (btrim(folio) <> ''::text))`),
    check('transactions_reference_not_blank', sql`((reference IS NULL) OR (btrim(reference) <> ''::text))`),
    check(
      'transactions_transfer_has_reference',
      sql`((payment_method <> 'transfer'::payment_method) OR (reference IS NOT NULL))`,
    ),
  ],
)

export const userRoles = pgTable.withRLS(
  'user_roles',
  {
    userId: uuid('user_id').notNull(),
    role: appRole().notNull(),
    grantedBy: uuid('granted_by'),
    createdAt: timestamp('created_at', { withTimezone: true })
      .default(sql`now()`)
      .notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.role], name: 'user_roles_pkey' }),
    foreignKey({
      columns: [table.grantedBy],
      foreignColumns: [profiles.id],
      name: 'user_roles_granted_by_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.userId],
      foreignColumns: [profiles.id],
      name: 'user_roles_user_id_fkey',
    }).onDelete('cascade'),
    index('user_roles_granted_by_idx').using('btree', table.grantedBy.asc().nullsLast()),

    pgPolicy('user_roles: admin can update', {
      for: 'update',
      to: ['authenticated'],
      using: sql`( SELECT private.is_admin() AS is_admin)`,
      withCheck: sql`( SELECT private.is_admin() AS is_admin)`,
    }),

    pgPolicy('user_roles: board managers can delete', {
      for: 'delete',
      to: ['authenticated'],
      using: sql`(( SELECT private.is_admin() AS is_admin) OR (( SELECT private.has_role('president'::app_role) AS has_role) AND (role <> 'admin'::app_role)))`,
    }),

    pgPolicy('user_roles: board managers can insert', {
      for: 'insert',
      to: ['authenticated'],
      withCheck: sql`(( SELECT private.is_admin() AS is_admin) OR (( SELECT private.has_role('president'::app_role) AS has_role) AND (role <> 'admin'::app_role)))`,
    }),

    pgPolicy('user_roles: members can read', { for: 'select', to: ['authenticated'], using: sql`true` }),
  ],
)
export const houseFeeStatus = pgView('house_fee_status', {
  propertyId: uuid('property_id'),
  number: text(),
  periodId: uuid('period_id'),
  monthsDue: integer('months_due'),
  monthsPaid: integer('months_paid'),
  unpaidMonths: date('unpaid_months').array(),
})
  .with({ securityInvoker: true })
  .as(
    sql`WITH current_period AS ( SELECT periods.id, periods.starts_on, periods.ends_on FROM periods WHERE CURRENT_DATE >= periods.starts_on AND CURRENT_DATE <= periods.ends_on ), due_months AS ( SELECT cp.id AS period_id, generate_series(date_trunc('month'::text, cp.starts_on::timestamp with time zone)::date::timestamp with time zone, date_trunc('month'::text, LEAST(CURRENT_DATE, cp.ends_on)::timestamp with time zone)::date::timestamp with time zone, '1 mon'::interval)::date AS fee_month FROM current_period cp ), fee_category AS ( SELECT transaction_categories.id FROM transaction_categories WHERE transaction_categories.key = 'fee'::text ) SELECT pr.id AS property_id, pr.number, dm.period_id, count(dm.fee_month)::integer AS months_due, count(t.id)::integer AS months_paid, COALESCE(array_agg(dm.fee_month ORDER BY dm.fee_month) FILTER (WHERE t.id IS NULL), '{}'::date[]) AS unpaid_months FROM properties pr CROSS JOIN due_months dm LEFT JOIN transactions t ON t.property_id = pr.id AND t.fee_month = dm.fee_month AND t.category_id = (( SELECT fee_category.id FROM fee_category)) AND t.deleted_at IS NULL WHERE pr.deleted_at IS NULL GROUP BY pr.id, pr.number, dm.period_id`,
  )

export const treasuryPeriodSummary = pgView('treasury_period_summary', {
  periodId: uuid('period_id'),
  currency: currencyCode(),
  totalIncome: numeric('total_income', { mode: 'number', precision: 12, scale: 2 }),
  totalExpense: numeric('total_expense', { mode: 'number', precision: 12, scale: 2 }),
  balance: numeric({ mode: 'number', precision: 12, scale: 2 }),
})
  .with({ securityInvoker: true })
  .as(
    sql`SELECT p.id AS period_id, COALESCE(t.currency, p.currency) AS currency, COALESCE(sum(t.amount) FILTER (WHERE t.kind = 'income'::transaction_kind), 0::numeric)::numeric(12,2) AS total_income, COALESCE(sum(t.amount) FILTER (WHERE t.kind = 'expense'::transaction_kind), 0::numeric)::numeric(12,2) AS total_expense, COALESCE(sum( CASE t.kind WHEN 'income'::transaction_kind THEN t.amount ELSE - t.amount END), 0::numeric)::numeric(12,2) AS balance FROM periods p LEFT JOIN transactions t ON t.period_id = p.id AND t.deleted_at IS NULL GROUP BY p.id, (COALESCE(t.currency, p.currency))`,
  )
